package fizeau

import (
	"context"
	"fmt"
	"sort"

	"github.com/DocumentDrivenDX/fizeau/internal/modelcatalog"
)

func (s *service) ListProfiles(_ context.Context) ([]ProfileInfo, error) {
	cat, err := modelcatalog.Default()
	if err != nil {
		return nil, err
	}
	meta := cat.Metadata()
	profiles := cat.Profiles()
	aliases := cat.Aliases()
	out := make([]ProfileInfo, 0, len(profiles)+len(aliases))
	seen := make(map[string]struct{}, len(profiles)+len(aliases))
	for _, profile := range profiles {
		info := ProfileInfo{
			Name:                profile.Name,
			Target:              profile.Target,
			CompatibilityTarget: profile.CompatibilityTarget,
			MinPower:            profile.MinPower,
			MaxPower:            profile.MaxPower,
			ProviderPreference:  profile.ProviderPreference,
			CatalogVersion:      meta.CatalogVersion,
			ManifestSource:      meta.ManifestSource,
			ManifestVersion:     meta.ManifestVersion,
		}
		if profile.CompatibilityTarget != "" && profile.Name != profile.CompatibilityTarget {
			info.AliasOf = profile.CompatibilityTarget
		}
		out = append(out, info)
		seen[profile.Name] = struct{}{}
	}
	for _, alias := range aliases {
		if _, ok := seen[alias.Name]; ok {
			continue
		}
		out = append(out, ProfileInfo{
			Name:            alias.Name,
			Target:          alias.Target,
			AliasOf:         alias.Target,
			Deprecated:      alias.Deprecated,
			Replacement:     alias.Replacement,
			CatalogVersion:  meta.CatalogVersion,
			ManifestSource:  meta.ManifestSource,
			ManifestVersion: meta.ManifestVersion,
		})
	}
	sort.Slice(out, func(i, j int) bool {
		return out[i].Name < out[j].Name
	})
	return out, nil
}

func (s *service) ProfileAliases(_ context.Context) (map[string]string, error) {
	cat, err := modelcatalog.Default()
	if err != nil {
		return nil, err
	}
	out := make(map[string]string)
	for _, profile := range cat.Profiles() {
		if profile.CompatibilityTarget != "" && profile.Name != profile.CompatibilityTarget {
			out[profile.Name] = profile.CompatibilityTarget
		}
	}
	for _, alias := range cat.Aliases() {
		target := alias.Target
		if alias.Deprecated && alias.Replacement != "" {
			target = alias.Replacement
		}
		out[alias.Name] = target
	}
	return out, nil
}

func (s *service) ResolveProfile(_ context.Context, name string) (*ResolvedProfile, error) {
	cat, err := modelcatalog.Default()
	if err != nil {
		return nil, err
	}
	meta := cat.Metadata()
	profile, ok := cat.Profile(name)
	var compatTarget string
	var deprecated bool
	var replacement string
	if ok {
		compatTarget = profile.CompatibilityTarget
		if compatTarget == "" {
			compatTarget = profile.Target
		}
	}
	if !ok {
		var aliasTarget string
		for _, surface := range serviceProfileSurfaces() {
			target, err := cat.Resolve(name, modelcatalog.ResolveOptions{
				Surface:         surface.catalogSurface,
				AllowDeprecated: true,
			})
			if err != nil {
				if _, ok := err.(*modelcatalog.MissingSurfaceError); ok {
					continue
				}
				return nil, err
			}
			aliasTarget = target.CanonicalID
			if target.Deprecated && target.Replacement != "" {
				deprecated = true
				replacement = target.Replacement
				aliasTarget = target.Replacement
			} else if target.Deprecated {
				deprecated = true
			}
			break
		}
		if aliasTarget == "" {
			return nil, fmt.Errorf("profile %q is not defined in the catalog", name)
		}
		if resolvedProfile, ok := cat.Profile(aliasTarget); ok {
			profile = resolvedProfile
			compatTarget = profile.CompatibilityTarget
			if compatTarget == "" {
				compatTarget = profile.Target
			}
		} else {
			for _, candidate := range cat.Profiles() {
				if candidate.CompatibilityTarget == aliasTarget || candidate.Target == aliasTarget {
					profile = candidate
					compatTarget = candidate.CompatibilityTarget
					if compatTarget == "" {
						compatTarget = candidate.Target
					}
					break
				}
			}
		}

		return true
	default:
		return false
	}
}

func (s *service) applyEndpointRoutingCost(entry *routing.ProviderEntry, pcfg ServiceProviderEntry, cat *modelcatalog.Catalog) {
	if entry == nil {
		return
	}
	if providerTypeIsLocalEndpoint(pcfg.Type) {
		if s.opts.LocalCostUSDPer1kTokens > 0 {
			entry.CostUSDPer1kTokens = s.opts.LocalCostUSDPer1kTokens
			entry.CostSource = routing.CostSourceUserConfig
		} else {
			entry.CostUSDPer1kTokens = 0
			entry.CostSource = routing.CostSourceUnknown
		}
		return
	}
	if cost, ok := catalogCostUSDPer1kTokens(cat, entry.DefaultModel); ok {
		entry.CostUSDPer1kTokens = cost
		entry.CostSource = routing.CostSourceCatalog
		return
	}
	entry.CostUSDPer1kTokens = 0
	entry.CostSource = routing.CostSourceUnknown
}

func (s *service) applySubscriptionRoutingCost(entry *routing.HarnessEntry, cat *modelcatalog.Catalog) {
	if entry == nil || !entry.IsSubscription {
		return
	}
	baseCost, ok := catalogCostUSDPer1kTokens(cat, entry.DefaultModel)
	if !ok {
		baseCost, ok = catalogCostUSDPer1kTokens(cat, subscriptionFallbackProfile(entry.Name))
		if !ok {
			baseCost = 0
		}
	}
	cost := subscriptionEffectiveCostUSDPer1kTokens(baseCost, entry.QuotaPercentUsed, s.subscriptionCostCurve())
	entry.Providers = []routing.ProviderEntry{{
		CostUSDPer1kTokens: cost,
		CostSource:         routing.CostSourceSubscription,
	}}
}

func providerTypeIsLocalEndpoint(providerType string) bool {
	switch normalizeServiceProviderType(providerType) {
	case "lmstudio", "llama-server", "omlx", "rapid-mlx", "ollama", "lucebox", "vllm":
		return true
	default:
		return false
	}
}

func providerRoutingCostClass(providerType string) string {
	if providerTypeIsLocalEndpoint(providerType) {
		return "local"
	}
	return "medium"
}

func subscriptionFallbackProfile(harnessName string) string {
	switch harnessName {
	case "claude", "codex", "gemini":
		return "standard"
	default:
		return ""
	}
