 45		cat := serviceRoutingCatalog()
 46		profile := req.Profile
 47		modelRef := req.ModelRef
 48		providerPreference, err := providerPreferenceForProfile(cat, profile)
 49		if err != nil {
 50			return &RouteDecision{}, err
 51		}
 52		powerPolicy := RoutePowerPolicy{
 53			Profile:  profile,
 54			MinPower: req.MinPower,
 55			MaxPower: req.MaxPower,
 56		}
 57		if req.Model == "" && req.Provider == "" && req.Harness == "" {
 58			powerPolicy, err = effectiveRoutePowerPolicy(cat, profile, req.MinPower, req.MaxPower)
 59			if err != nil {
 60				return &RouteDecision{}, err
 61			}
 62		}
 63		in := s.buildRoutingInputsWithCatalog(ctx, cat)
 64	
 65		resolvedModel, modelCandidates, modelErr := s.resolveModelConstraint(req.Harness, req.Provider, req.Model, in, cat)
 66		if modelErr != nil {
 67			result := &RouteDecision{Candidates: modelCandidates}
 68			s.annotateRouteDecisionEvidence(result)
