 81			EstimatedPromptTokens: req.EstimatedPromptTokens,
 82			RequiresTools:         req.RequiresTools,
 83			MinPower:              powerPolicy.MinPower,
 84			MaxPower:              powerPolicy.MaxPower,
 85		}
 86		s.applyRouteAttemptCooldowns(&in)
 87		dec, err := routing.Resolve(rReq, in)
 88		if err != nil {
 89			if escalated, edec, eerr := escalateProfileLadder(rReq, in, err); escalated {
 90				dec = edec
