100			return result, publicRoutingError(err, result.Candidates)
101		}
102		s.applyStickyRouteLease(req.CorrelationID, result)
103		if result != nil && result.Endpoint == "" {
104			_, endpoint, _ := splitEndpointProviderRef(result.Provider)
105			result.Endpoint = endpoint
106		}
107		s.annotateRouteDecisionEvidence(result)
108		// Cache the decision so RouteStatus can surface LastDecision.
