277	func TestBuildRoutingInputs_GeminiQuotaGatesAutoRouting(t *testing.T) {
278		dir := t.TempDir()
279		quotaPath := filepath.Join(dir, "gemini-quota.json")
280		t.Setenv("FIZEAU_GEMINI_QUOTA_CACHE", quotaPath)
281		t.Setenv("FIZEAU_CODEX_QUOTA_CACHE", filepath.Join(dir, "missing-codex-quota.json"))
282		t.Setenv("FIZEAU_CLAUDE_QUOTA_CACHE", filepath.Join(dir, "missing-claude-quota.json"))
283	
284		registry := harnesses.NewRegistry()
285		svc := &service{opts: ServiceOptions{}, registry: registry}
286	
287		// Missing cache: no SubscriptionOK even with fresh auth.
288		t.Setenv("GOOGLE_API_KEY", "test")
289		gemini := routingHarnessEntry(t, svc.buildRoutingInputs(context.Background()).Harnesses, "gemini")
290		if gemini.SubscriptionOK || gemini.QuotaOK {
291			t.Fatalf("missing gemini quota cache must keep gemini out of auto-routing: %+v", gemini)
292		}
293	
294		// Stale snapshot: ineligible even though windows show headroom.
295		if err := geminiharness.WriteGeminiQuota(quotaPath, geminiharness.GeminiQuotaSnapshot{
296			CapturedAt: time.Now().UTC().Add(-1 * time.Hour),
297			Source:     "pty",
298			Windows: []harnesses.QuotaWindow{
299				{Name: "Flash", LimitID: "gemini-flash", UsedPercent: 4, State: "ok"},
300			},
301		}); err != nil {
302			t.Fatalf("WriteGeminiQuota stale: %v", err)
303		}
304		gemini = routingHarnessEntry(t, svc.buildRoutingInputs(context.Background()).Harnesses, "gemini")
305		if gemini.SubscriptionOK || !gemini.QuotaStale {
306			t.Fatalf("stale gemini quota: SubscriptionOK=%v QuotaStale=%v", gemini.SubscriptionOK, gemini.QuotaStale)
307		}
308	
309		// Fresh but all tiers exhausted: routing must still mark ineligible.
310		if err := geminiharness.WriteGeminiQuota(quotaPath, geminiharness.GeminiQuotaSnapshot{
311			CapturedAt: time.Now().UTC(),
312			Source:     "pty",
313			Windows: []harnesses.QuotaWindow{
314				{Name: "Flash", LimitID: "gemini-flash", UsedPercent: 100, State: "exhausted"},
315				{Name: "Pro", LimitID: "gemini-pro", UsedPercent: 100, State: "exhausted"},
316			},
317		}); err != nil {
318			t.Fatalf("WriteGeminiQuota exhausted: %v", err)
319		}
320		gemini = routingHarnessEntry(t, svc.buildRoutingInputs(context.Background()).Harnesses, "gemini")
321		if gemini.SubscriptionOK {
322			t.Fatalf("all tiers exhausted must block gemini auto-routing: %+v", gemini)
323		}
324		if gemini.QuotaTrend != routing.QuotaTrendExhausting {
325			t.Fatalf("all-exhausted snapshot should report exhausting trend, got %q", gemini.QuotaTrend)
326		}
327	
328		// Fresh with at least one non-exhausted tier: routing marks eligible.
329		if err := geminiharness.WriteGeminiQuota(quotaPath, geminiharness.GeminiQuotaSnapshot{
330			CapturedAt: time.Now().UTC(),
331			Source:     "pty",
332			Windows: []harnesses.QuotaWindow{
333				{Name: "Flash", LimitID: "gemini-flash", UsedPercent: 4, State: "ok"},
334				{Name: "Pro", LimitID: "gemini-pro", UsedPercent: 100, State: "exhausted"},
335			},
336		}); err != nil {
337			t.Fatalf("WriteGeminiQuota ok: %v", err)
338		}
339		gemini = routingHarnessEntry(t, svc.buildRoutingInputs(context.Background()).Harnesses, "gemini")
340		if !gemini.SubscriptionOK || !gemini.QuotaOK {
341			t.Fatalf("fresh gemini quota with headroom should mark gemini SubscriptionOK/QuotaOK: %+v", gemini)
342		}
343	}
